package com.nexushr.entity;
import jakarta.persistence.*; import java.time.*; import java.util.UUID;
@Entity @Table(name="leave_requests") public class LeaveRequest { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @ManyToOne(optional=false) private Employee employee; @Enumerated(EnumType.STRING) @Column(nullable=false) private LeaveType type; @Column(nullable=false) private LocalDate startDate; @Column(nullable=false) private LocalDate endDate; @Column(nullable=false) private String reason; @Enumerated(EnumType.STRING) @Column(nullable=false) private LeaveStatus status=LeaveStatus.PENDING; private String reviewerComment; private LocalDateTime createdAt=LocalDateTime.now(); public UUID getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public LeaveType getType(){return type;} public void setType(LeaveType v){type=v;} public LocalDate getStartDate(){return startDate;} public void setStartDate(LocalDate v){startDate=v;} public LocalDate getEndDate(){return endDate;} public void setEndDate(LocalDate v){endDate=v;} public String getReason(){return reason;} public void setReason(String v){reason=v;} public LeaveStatus getStatus(){return status;} public void setStatus(LeaveStatus v){status=v;} public String getReviewerComment(){return reviewerComment;} public void setReviewerComment(String v){reviewerComment=v;} public LocalDateTime getCreatedAt(){return createdAt;} }
